scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? "#" +
        ("0" + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[3], 10).toString(16)).slice(-2) : '';
}
scwin._checkRgb = function(id, hexa) {
    var rgb = WebSquare.wUnit.getJq("#" + id).css("background-color");
    var color;
    if (rgb.indexOf("rgb") != -1) {
        color = scwin.rgb2hex(rgb);
        return color == hexa;
    }
    return rgb == hexa;
}
scwin.checkSimulate = function() {
    scwin.simulateWrapper('#gridView1_cell_0_12', 'key-combo', {
        combo: 'TAB'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. WebSquare5 에서 config.xml 에 속성을 추가한다. (Test Data 내용확인)
    //1. In WebSquare5, add the attribute to config.xml. (Confirm Test Data Contents)
    //Verify step 1. Add properties
    //Test step 2. 브라우저에서 checkcombobox 컬럼 (직업)을 클릭한다.
    //2. In the browser, click the checkcombobox column (occupation).
    //Verify step 2. The job list is activated.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollX_right').scrollLeft = 150");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_12').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_gridView1___checkcombobox_WORK_itemTable').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. Tab 키를 누른다.
    //3. Press the Tab key.
    //Verify step 3. Move to the next key, the key.
    WebSquare.wUnit.addCommand("set", "scwin.checkSimulate()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb($p.id+'gridView1_cell_0_13', '#fca73c')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. 첫번째 그리드에서 혈액형을 변경한다.
    //4. Change the blood type on the first grid.
    //Verify step 4. As the blood type changes, the blood type of the second grid changes as well.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_10')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___selectbox_BLOOD_TYPE_itemTable_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_12_cell_0_9').text().trim() == 'A형'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.initialize();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 05-May-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
